/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_PRODUCT_RATING_STRUCTURE
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_PRODUCT   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PRODUCT_HK
   hashdiff    : SAT_PRODUCT_RATING_STRUCTURE_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE_PLAN_ID))) as HUB_PRODUCT_HK
        , LOADER_YN as PREMIUM_LOADING_APPLICABLE_INDICATOR
        , PREMIUM_LIMIT as MAXIMUM_PREMIUM_PERMITTED
        , 'BJAZ_CTNGY_SCHEME_PLANS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_plans') }}
    where (nullif('SCHEMEPLAN:' || nullif(trim(SCHEME_CODE),'') || '|' || nullif(trim(PLAN_ID),''), 'SCHEMEPLAN:|')) is not null
),

resolved as (
    select
        HUB_PRODUCT_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then PREMIUM_LOADING_APPLICABLE_INDICATOR end) as PREMIUM_LOADING_APPLICABLE_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then MAXIMUM_PREMIUM_PERMITTED end) as MAXIMUM_PREMIUM_PERMITTED,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PRODUCT_HK
),

hashed as (
    select
        *,
        case when PREMIUM_LOADING_APPLICABLE_INDICATOR is not null or MAXIMUM_PREMIUM_PERMITTED is not null
                     then md5(upper(coalesce(cast(PREMIUM_LOADING_APPLICABLE_INDICATOR as varchar), '') || '|' || coalesce(cast(MAXIMUM_PREMIUM_PERMITTED as varchar), '')))
                end as SAT_PRODUCT_RATING_STRUCTURE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PRODUCT_HK is not null
  and SAT_PRODUCT_RATING_STRUCTURE_HASHDIFF is not null
